import{_ as t,c as e,a2 as l,o as i}from"./chunks/framework.DpbDeoNR.js";const o="/pub-blog/assets/image-20260104230740217.q88nlwml.png",r="/pub-blog/assets/image-20260104230758427.K2_46wl5.png",n="/pub-blog/assets/asynccode.SzD6pBrn.png",h="/pub-blog/assets/image-20260104230821064.DUFb_m1W.png",q=JSON.parse('{"title":"AI 玩转鸿蒙 （一）：选择合适的AI开发工具","description":"","frontmatter":{},"headers":[],"relativePath":"AI 玩转鸿蒙/AI 玩转鸿蒙 （一）：选择合适的AI开发工具/AI 玩转鸿蒙 （一）：选择合适的AI开发工具.md","filePath":"AI 玩转鸿蒙/AI 玩转鸿蒙 （一）：选择合适的AI开发工具/AI 玩转鸿蒙 （一）：选择合适的AI开发工具.md","lastUpdated":1767539633000}'),d={name:"AI 玩转鸿蒙/AI 玩转鸿蒙 （一）：选择合适的AI开发工具/AI 玩转鸿蒙 （一）：选择合适的AI开发工具.md"};function s(u,a,c,b,_,g){return i(),e("div",null,a[0]||(a[0]=[l('<h1 id="ai-玩转鸿蒙-一-选择合适的ai开发工具" tabindex="-1">AI 玩转鸿蒙 （一）：选择合适的AI开发工具 <a class="header-anchor" href="#ai-玩转鸿蒙-一-选择合适的ai开发工具" aria-label="Permalink to &quot;AI 玩转鸿蒙 （一）：选择合适的AI开发工具&quot;">​</a></h1><blockquote><p><strong>分享人</strong>：万少<br><strong>日期</strong>：2026年1月4日<br><strong>主题</strong>：AI编程工具实践与鸿蒙最新代码生成技巧</p></blockquote><hr><h1 id="_1-ai编辑器工具" tabindex="-1">1. AI编辑器工具 <a class="header-anchor" href="#_1-ai编辑器工具" aria-label="Permalink to &quot;1. AI编辑器工具&quot;">​</a></h1><h2 id="_1-1-ai-ide-工具" tabindex="-1">1.1 AI IDE 工具 <a class="header-anchor" href="#_1-1-ai-ide-工具" aria-label="Permalink to &quot;1.1 AI IDE 工具&quot;">​</a></h2><h3 id="gemini-3-pro" tabindex="-1">Gemini-3-pro <a class="header-anchor" href="#gemini-3-pro" aria-label="Permalink to &quot;Gemini-3-pro&quot;">​</a></h3><ul><li><strong>Trae 海外版</strong>： <ul><li>使用门槛：需要梯子，有费用成本</li><li>年度会员包含：Claude 4.5等 -&gt; <strong>谷歌 Gemini-3-pro：能用自然语言编写功能</strong></li><li>示例：<code>Gemini-3-pro：帮我使用某个mp4充当开屏动画</code></li></ul></li><li><strong>Trae 国内版</strong>： <ul><li>使用国内主流大模型</li><li>推理能力：<strong>是否能识别图片</strong>（豆包1.8可以识别截图）</li></ul></li></ul><h3 id="glm4-6" tabindex="-1">GLM4.6 <a class="header-anchor" href="#glm4-6" aria-label="Permalink to &quot;GLM4.6&quot;">​</a></h3><ul><li>示例：<code>GLM4.6: 使用 xxx/1.mp4 在 Start.ets 中实现开屏动画，播放5s后，跳转到Index.ets</code></li></ul><h3 id="codebuddy" tabindex="-1">Codebuddy <a class="header-anchor" href="#codebuddy" aria-label="Permalink to &quot;Codebuddy&quot;">​</a></h3><ul><li><strong>海外版</strong>：考虑后端部署（数据库+后端程序），直连腾讯云相关服务</li><li><strong>国内版</strong>：直连腾讯云相关服务</li></ul><h3 id="阿里-qoder" tabindex="-1">阿里 QOder <a class="header-anchor" href="#阿里-qoder" aria-label="Permalink to &quot;阿里 QOder&quot;">​</a></h3><ul><li>编写鸿蒙语言很准确，语法都对</li><li>10月份：one！！！</li><li>价格：<strong>拉满一年 8k</strong></li></ul><h2 id="_1-2-ai-终端工具" tabindex="-1">1.2 AI 终端工具 <a class="header-anchor" href="#_1-2-ai-终端工具" aria-label="Permalink to &quot;1.2 AI 终端工具&quot;">​</a></h2><h3 id="iflow-cli" tabindex="-1">IFlow Cli <a class="header-anchor" href="#iflow-cli" aria-label="Permalink to &quot;IFlow Cli&quot;">​</a></h3><ul><li>内置国内大模型 -&gt; <strong>GLM 4.6 生成70%代码</strong></li><li>阿里团队出品，心流团队</li><li>号称永久免费！！</li><li>可配置其他大模型，需要api-token</li></ul><h3 id="claude-code" tabindex="-1">Claude code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude code&quot;">​</a></h3><ul><li>不稳定，需要中转，体验较差</li><li>享受不到AI帮我打工的感觉</li><li>官网言论：我也不喜欢，不想让它赚钱</li></ul><h2 id="_1-3-第三方-ai-api" tabindex="-1">1.3 第三方 AI API <a class="header-anchor" href="#_1-3-第三方-ai-api" aria-label="Permalink to &quot;1.3 第三方 AI API&quot;">​</a></h2><h2 id="_1-4-万少ai编辑器总结" tabindex="-1">1.4 万少AI编辑器总结 <a class="header-anchor" href="#_1-4-万少ai编辑器总结" aria-label="Permalink to &quot;1.4 万少AI编辑器总结&quot;">​</a></h2><ul><li><strong>Trae 海外版</strong>：Gemini-3-pro，会员年费600多人民币</li><li><strong>国内版</strong>：GLM4.7</li></ul><h1 id="_2-app图片处理" tabindex="-1">2. APP图片处理 <a class="header-anchor" href="#_2-app图片处理" aria-label="Permalink to &quot;2. APP图片处理&quot;">​</a></h1><h2 id="_2-1-图片生成问题" tabindex="-1">2.1 图片生成问题 <a class="header-anchor" href="#_2-1-图片生成问题" aria-label="Permalink to &quot;2.1 图片生成问题&quot;">​</a></h2><ul><li><strong>豆包生成图片</strong>：有AI标识</li><li><strong>解决方案</strong>：使用百度图片工具移除豆包图片的AI标识</li></ul><h2 id="_2-2-图片示例" tabindex="-1">2.2 图片示例 <a class="header-anchor" href="#_2-2-图片示例" aria-label="Permalink to &quot;2.2 图片示例&quot;">​</a></h2><p><img src="'+o+'" alt="image-20260104230740217"></p><h1 id="_3-如何保证生成的鸿蒙代码是最新的" tabindex="-1">3. 如何保证生成的鸿蒙代码是最新的 <a class="header-anchor" href="#_3-如何保证生成的鸿蒙代码是最新的" aria-label="Permalink to &quot;3. 如何保证生成的鸿蒙代码是最新的&quot;">​</a></h1><blockquote><p><strong>问题</strong>：旧的鸿蒙代码都不是API11及以上版本，api9、java版本代码错乱</p></blockquote><h2 id="_3-1-配置mcp工具-context7" tabindex="-1">3.1 配置MCP工具 - Context7 <a class="header-anchor" href="#_3-1-配置mcp工具-context7" aria-label="Permalink to &quot;3.1 配置MCP工具 - Context7&quot;">​</a></h2><blockquote><p>各大AI编辑器的官网都会有对应的配置方法</p></blockquote><p><strong>Context7能力</strong>：自动搜索其库中最新的鸿蒙文档和语法</p><ul><li>万少已将鸿蒙开发文档（1w多个文档）全部上传到Context7</li><li>支持API20等最新版本</li></ul><p>使用方法</p><blockquote><p>帮我生成xx代码 use Context</p></blockquote><h2 id="_3-2-文档喂给ai的方法" tabindex="-1">3.2 文档喂给AI的方法 <a class="header-anchor" href="#_3-2-文档喂给ai的方法" aria-label="Permalink to &quot;3.2 文档喂给AI的方法&quot;">​</a></h2><h3 id="_3-2-1-直接喂网址" tabindex="-1">3.2.1 直接喂网址 <a class="header-anchor" href="#_3-2-1-直接喂网址" aria-label="Permalink to &quot;3.2.1 直接喂网址&quot;">​</a></h3><ul><li>使用谷歌Gemini-3是可行的</li></ul><h3 id="_3-2-2-保存网址为md文档后喂给ai" tabindex="-1">3.2.2 保存网址为MD文档后喂给AI <a class="header-anchor" href="#_3-2-2-保存网址为md文档后喂给ai" aria-label="Permalink to &quot;3.2.2 保存网址为MD文档后喂给AI&quot;">​</a></h3><p><img src="'+r+'" alt="image-20260104230758427"></p><p><img src="'+n+'" alt="保存网址为MD"></p><h3 id="_3-2-3-推荐使用万少ima知识库" tabindex="-1">3.2.3 推荐使用万少IMA知识库 <a class="header-anchor" href="#_3-2-3-推荐使用万少ima知识库" aria-label="Permalink to &quot;3.2.3 推荐使用万少IMA知识库&quot;">​</a></h3><p><img src="'+h+'" alt="image-20260104230821064"></p><h1 id="_4-下期预告" tabindex="-1">4. 下期预告 <a class="header-anchor" href="#_4-下期预告" aria-label="Permalink to &quot;4. 下期预告&quot;">​</a></h1><h2 id="_4-1-主题-如何在鸿蒙中直接生成图片素材及使用" tabindex="-1">4.1 主题：如何在鸿蒙中直接生成图片素材及使用 <a class="header-anchor" href="#_4-1-主题-如何在鸿蒙中直接生成图片素材及使用" aria-label="Permalink to &quot;4.1 主题：如何在鸿蒙中直接生成图片素材及使用&quot;">​</a></h2><h3 id="_4-1-1-直接生成svg图片图标" tabindex="-1">4.1.1 直接生成SVG图片图标 <a class="header-anchor" href="#_4-1-1-直接生成svg图片图标" aria-label="Permalink to &quot;4.1.1 直接生成SVG图片图标&quot;">​</a></h3><h3 id="_4-1-2-页面素材配置脚本" tabindex="-1">4.1.2 页面素材配置脚本 <a class="header-anchor" href="#_4-1-2-页面素材配置脚本" aria-label="Permalink to &quot;4.1.2 页面素材配置脚本&quot;">​</a></h3><hr><h1 id="_5-总结与实用建议" tabindex="-1">5. 总结与实用建议 <a class="header-anchor" href="#_5-总结与实用建议" aria-label="Permalink to &quot;5. 总结与实用建议&quot;">​</a></h1><h2 id="_5-1-工具选择建议" tabindex="-1">5.1 工具选择建议 <a class="header-anchor" href="#_5-1-工具选择建议" aria-label="Permalink to &quot;5.1 工具选择建议&quot;">​</a></h2><h3 id="对于国内开发者" tabindex="-1">对于国内开发者： <a class="header-anchor" href="#对于国内开发者" aria-label="Permalink to &quot;对于国内开发者：&quot;">​</a></h3><ol><li><strong>IFlow Cli</strong>：免费，内置GLM4.6，适合日常开发</li><li><strong>Trae国内版</strong>：使用国内大模型，无需梯子</li><li><strong>豆包1.8</strong>：图片识别能力强</li></ol><h3 id="对于海外或有梯子的开发者" tabindex="-1">对于海外或有梯子的开发者： <a class="header-anchor" href="#对于海外或有梯子的开发者" aria-label="Permalink to &quot;对于海外或有梯子的开发者：&quot;">​</a></h3><ol><li><strong>Gemini-3-pro</strong>：自然语言编程能力强</li><li><strong>Trae海外版</strong>：功能全面，但需要会员</li></ol><h2 id="_5-2-鸿蒙开发最佳实践" tabindex="-1">5.2 鸿蒙开发最佳实践 <a class="header-anchor" href="#_5-2-鸿蒙开发最佳实践" aria-label="Permalink to &quot;5.2 鸿蒙开发最佳实践&quot;">​</a></h2><ol><li><strong>一定要使用Context7</strong>：确保生成的代码是最新API版本</li><li><strong>文档预处理</strong>：将官方文档保存为MD格式再喂给AI</li><li><strong>版本验证</strong>：生成代码后检查API版本号</li></ol><h2 id="_5-3-成本考虑" tabindex="-1">5.3 成本考虑 <a class="header-anchor" href="#_5-3-成本考虑" aria-label="Permalink to &quot;5.3 成本考虑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>费用</th><th>适合人群</th></tr></thead><tbody><tr><td>IFlow Cli</td><td>免费</td><td>所有开发者</td></tr><tr><td>Trae海外版</td><td>600+/年</td><td>专业开发者</td></tr><tr><td>阿里QOder</td><td>8000/年</td><td>企业级鸿蒙开发</td></tr></tbody></table><hr><p><strong>分享要点回顾</strong>：</p><ol><li>AI编程工具能显著提升开发效率</li><li>鸿蒙开发要注意API版本兼容性</li><li>正确的工具配置是关键</li><li>下期将深入图片素材生成</li></ol><p><strong>Q&amp;A环节准备问题</strong>：</p><ol><li>如何选择适合自己的AI编程工具？</li><li>Context7的具体配置步骤？</li><li>鸿蒙API版本升级的注意事项？</li></ol>',62)]))}const p=t(d,[["render",s]]);export{q as __pageData,p as default};
